    padding: 10px 0px 0px 30px;
    color: $white-text;
    font-weight: 300;
  }

  .lobby-name {
    color: $white-text;
    font-size: 25px;
    font-weight: 300;
    display: flex;
  }

  .players {
    flex: 0.3;
    font-size: 20px;
    display: flex;
    justify-content: center;
    align-items: center;
    color: $white-text;

    .lobby-stats {
      margin-right: 7px;
      font-weight: 300;
    }

    .fas {
      color: lighten($foreground, 20%);
      font-size: 25px;
    }
  }

  .join {
    display: flex;
    justify-content: center;
    align-items: center;
    flex: 0.4;
  }

  .join-button {
    background: none;
