<template>
  <div class="tab-content" v-show="title === selectedTitle">
    <transition name="tab-anim" appear>
      <div style="overflow: visible" v-show="title === selectedTitle">
        <slot/>
      </div>
    </transition>
  </div>
</template>

<script>
import {inject} from 'vue';

export default {
  name: "LoadoutTab",
  props: ['title'],
  setup() {
    const selectedTitle = inject("selectedTitle")

    return {
      selectedTitle
    }
  }
}
</script>

<style scoped lang="scss">
.tab-anim-enter-active {
  animation: fade-in 0.5s cubic-bezier(0.390, 0.575, 0.565, 1.000) both;
}

@keyframes fade-in {
  0% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}
</style>