<template>
  <div class="setting">
    <label :id="id">{{ label }}</label>
    <ul class="radios">
      <li v-for="(option, index) in options" :key="option">
        <input type="radio" :id="index" :name="id" :value="option.value" @change="change" v-model="value"/>
        <label :for="index">{{ option.name }}</label>
      </li>
    </ul>
    <small>{{ description }}</small>
  </div>
</template>

<script>
export default {
  name: "RadioOption",
  props: ['id', 'label', 'name', 'description', 'options'],
  data() {
    return {
      value: '1000'
    }
  },
  methods: {
    change() {
      // eslint-disable-next-line no-undef
      mp.trigger('MenuChangeSettings', this.id, this.value);
    }
  },
}
</script>

<style scoped lang="scss">
.radios {
  list-style-type: none;
  margin: 10px 0;
  padding: 0;

  li {
    float: left;
    margin: 0 5px 0 0;
    width: 100px;
    height: 40px;
    position: relative;
  }

  & label, & input {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    display: flex;
    justify-content: center;
    align-items: center;
    transition: all 0.4s;
    border-radius: 15px;
    color: $white-text;
  }

  & input[type="radio"] {
    opacity: 0.011;
    z-index: 100;
  }

  & input[type="radio"]:checked + label {
    background: $blue;
    border-color: $blue;
  }

  & label {
    padding: 5px;
    border: 2px solid rgb(78, 78, 78);
    cursor: pointer;
    z-index: 90;
  }

  & label:hover {
    background: $blue;
    border-color: $blue;
  }
}

.setting {
  color: $white-text;
  margin-bottom: 15px;
  display: flex;
  flex-direction: column;

  .top {
    display: flex;
    justify-content: flex-start;
    align-items: center;

    label {
      margin-right: 10px;
    }
  }

  small {
    color: $gray-text;
  }
}
</style>