<template>
  <div class="tab-content" v-show="title === selectedTitle">
    <div class="top tabDraggable">
      {{ selectedTitle }}
    </div>
      <div class="bottom">
        <transition name="tab-anim" appear>
          <div style="overflow: visible" v-show="title === selectedTitle">
            <slot/>
          </div>
        </transition>
      </div>
  </div>
</template>

<script>
import {inject} from 'vue';

export default {
  name: "Tab",
  props: ['title'],
  setup() {
    const selectedTitle = inject("selectedTitle")

    return {
      selectedTitle
    }
  }
}
</script>

<style scoped lang="scss">
.tab-anim-enter-active {
  animation: fade-in 0.5s cubic-bezier(0.390, 0.575, 0.565, 1.000) both;
}

@keyframes fade-in {
  0% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}

.top {
  height: 60px;
  display: flex;
  align-items: center;
  padding: 20px 0px 20px 30px;
  font-size: 22px;
  color: #fff;
  //border-bottom: 1px solid $sago-gray2;
  background: $foreground;
  //box-shadow: rgba(0, 0, 0, 0.35) 0px 5px 15px;
}

.bottom {
  background: $background;
  border-radius: 15px;
  flex: 1;
  padding: 10px;
  box-shadow: rgba(0, 0, 0, 0.35) 0px 5px 15px inset;
  overflow: visible !important;
}

.tab-content {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
}
</style>