<template>
  <div class="tabs">
    <ul class="tabs_header">
      <div class="logo">
        <img @mouseover="logoURL = `https://i.imgur.com/2sSNYzF.png`" @mouseleave="logoURL = `https://i.imgur.com/S9m1NVy.png`" :src="logoURL" alt="lscc">
      </div>
      <li class="tab_header" v-for="tab in tabTitles" :key="tab.title" :class="{selected: tab.title === selectedTitle}" @click="selectedTitle = tab.title">
        <i :class="['bx', tab.icon]"></i>
        {{ tab.title }}
      </li>
    </ul>
    <slot/>
  </div>
</template>

<script>
import { ref, provide } from 'vue';

export default {
  name: "TabsWrapper",
  data() {
    return {
      logoURL: `https://i.imgur.com/S9m1NVy.png`
    }
  },
  setup(props, {slots}) {
    const tabTitles = ref(slots.default().map((tab) => tab.props))
    const selectedTitle = ref(tabTitles.value[0].title)

    provide("selectedTitle", selectedTitle)
    return {
      selectedTitle,
      tabTitles
    }
  }
}
</script>

<style scoped lang="scss">
.tabs {
  font-family: 'Nunito', sans-serif;
  font-weight: bold;
  display: flex;
  height: 100%;
  width: 100%;
}

.bx {
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 27px;
}

.logo {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 10px  0px 5px 0px;

  //background: #2d6ae3;

  img {
    width: 50px;
    -webkit-user-drag: none;
  }
}

.tabs_header {
  height: 100%;
  width: 120px;
  color: $gray-text;
  //border-right: 1px solid $sago-gray2;
  font-size: 15px;
  background: $foreground;
  //box-shadow: rgba(0, 0, 0, 0.35) 0px 5px 15px;

  .selected {
    color: $white-text;
    transition: 0.4s;
    transition-property: color, text-shadow;
    //border-right: 1px solid #2d6ae3;

    text-shadow: 0 0 5px $white-text;
  }

  .tab_header {
    display: grid;
    justify-content: center;
    align-items: center;
    height: 50px;
    margin: 20px 0px;
    cursor: pointer;

    .bx {
      padding: 8px 0px;
    }
  }
}

</style>